167	diff --git a/src/explore/multi/lobby.ts b/src/explore/multi/lobby.ts
168	new file mode 100644
169	index 0000000..7f4811f
170	--- /dev/null
171	+++ b/src/explore/multi/lobby.ts
172	@@ -0,0 +1,93 @@
173	+/* ===== Dù lượn nhiều người: bước chọn slot và nhập tên (trong hộp thoại #chooser) =====
174	+   Hiện sau khi bấm thẻ Dù lượn lúc có máy chủ: 5 chấm + "Còn N trên 5 chỗ", tên những người đang bay, ô tên, nút Bay ngay.
175	+   Cập nhật trực tiếp theo MultiSession; tên người khác chỉ ghi bằng textContent. Tên của mình nhớ ở localStorage.
176	+   Pha lobby: cho nhập tên và giành chỗ. Pha solo (không kết nối được): báo ngoại tuyến + nút Bay một mình.
177	+   Pha flying: gọi onFly. Pha watching (hết chỗ): gọi onWatch (chế độ xem do Task 7 làm). */
178	+import { CONFIG } from '../../config';
179	+import { t, onChange as onLang } from '../../i18n';
180	+import { exMulti } from './index';
181	+import { exSanitizeName } from './protocol';
182	+import type { MultiSession } from './session';
183	+
184	+export interface LobbyCallbacks { onFly: () => void; onWatch: () => void; onSolo: () => void }
185	+
186	+const M = CONFIG.explore.multi;
187	+const NAME_KEY = 'exMpName';
188	+const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
189	+
190	+function loadName(): string { try { return localStorage.getItem(NAME_KEY) || ''; } catch { return ''; } }
191	+function saveName(n: string): void { try { localStorage.setItem(NAME_KEY, n); } catch { /* bộ nhớ trình duyệt bị chặn */ } }
192	+
193	+let listKey = '';
194	+let langBound = false;
195	+let redraw: (() => void) | null = null;
196	+
197	+/* Hiện bước riêng thay cho các thẻ và gắn nó vào phiên; trả ngay (phiên đang ở pha 'connecting') */
198	+export function exShowLobby(session: MultiSession, cb: LobbyCallbacks): void {
199	+  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement;
200	+  const input = $<HTMLInputElement>('exMpNameIn'), fly = $<HTMLButtonElement>('exMpFly'), solo = $<HTMLButtonElement>('exMpSolo');
201	+  box.querySelector<HTMLElement>('.ex-cards')!.hidden = true;
202	+  $('exTitle').hidden = true;
203	+  box.setAttribute('aria-labelledby', 'exMpSky');
204	+  root.hidden = false;
205	+  if (!input.value) input.value = loadName();
206	+  listKey = '';
207	+  let done = false;
208	+  const finish = (f: () => void) => { if (done) return; done = true; exMulti.onChange = () => {}; redraw = null; f(); };
209	+
210	+  const render = () => {
211	+    if (done) return;
212	+    const ph = session.phase;
213	+    if (ph === 'flying') { finish(cb.onFly); return; }
214	+    if (ph === 'watching') { finish(cb.onWatch); return; }
215	+    const offline = ph === 'solo';
216	+    $('exMpOnline').hidden = offline;
217	+    $('exMpOffline').hidden = !offline;
218	+    solo.hidden = !offline;
219	+    if (offline) { if (document.activeElement !== solo) solo.focus({ preventScroll: true }); return; }
220	+    const ready = ph === 'lobby';
221	+    const free = M.slots - session.flyers.length;
222	+    $('exMpSeats').textContent = ready ? t('exMpSeats', { n: free }) : '…';
223	+    $('exMpNameHint').textContent = t('exMpNameMax', { n: M.nameMax });
224	+    const taken = new Set(session.flyers.map(f => f.slot));
225	+    $('exMpDots').querySelectorAll<HTMLElement>('i').forEach((d, i) => {
226	+      d.classList.toggle('on', taken.has(i));
227	+      d.style.background = taken.has(i) ? M.colors[i % M.colors.length] : '';
228	+    });
229	+    const key = session.flyers.map(f => f.slot + ':' + f.name).join('|');
230	+    if (key !== listKey) {
231	+      listKey = key;
232	+      const list = $('exMpList'); list.textContent = '';
233	+      for (const f of session.flyers) {
234	+        const row = document.createElement('div'); row.className = 'ex-mp-row';
235	+        const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
236	+        const nm = document.createElement('span'); nm.textContent = f.name; nm.dir = 'auto';
237	+        row.append(dot, nm); list.appendChild(row);
238	+      }
239	+    }
240	+    $('exMpNameBad').hidden = session.notice !== 'nameBad';
241	+    fly.disabled = !ready || exSanitizeName(input.value) === null;
242	+  };
243	+
244	+  const go = () => {
245	+    const name = exSanitizeName(input.value);
246	+    if (name === null || session.phase !== 'lobby') return;
247	+    saveName(name);
248	+    session.join(name);
249	+  };
250	+  input.addEventListener('input', () => {
251	+    $('exMpNameBad').hidden = true;
252	+    const ok = exSanitizeName(input.value);
253	+    if (ok !== null) saveName(ok);   // nhớ ngay khi hợp lệ, tải lại trang vẫn còn
254	+    fly.disabled = session.phase !== 'lobby' || ok === null;
255	+  });
256	+  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); go(); } });
257	+  fly.addEventListener('click', go);
258	+  solo.addEventListener('click', () => finish(cb.onSolo), { once: true });
259	+
260	+  redraw = render;
261	+  if (!langBound) { langBound = true; onLang(() => { if (redraw) redraw(); }); }
262	+  exMulti.onChange = render;
263	+  render();
264	+  input.focus({ preventScroll: true });
265	+}
