+.ex-mp-lobby h2{margin:0;}
+.ex-mp-seatline{display:flex;align-items:center;gap:10px;font-size:13px;color:var(--text);}
+#exMpDots{display:inline-flex;gap:6px;flex:none;}
+#exMpDots i{width:12px;height:12px;border-radius:50%;box-sizing:border-box;border:1.5px solid var(--gold);background:transparent;}
+#exMpDots i.on{border-color:transparent;}
+#exMpList{display:flex;flex-direction:column;font-size:13px;}
+#exMpList .ex-mp-row{padding:4px 0;border-bottom:1px solid rgba(255,255,255,.08);overflow-wrap:anywhere;}
+#exMpList .ex-mp-row i{width:9px;height:9px;border-radius:50%;flex:none;}
+.ex-mp-field{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--muted);}
+.ex-mp-field input{font:500 14px/1.2 var(--font-body);color:var(--text);background:rgba(0,0,0,.35);border:1px solid var(--gold);border-radius:4px;padding:8px 10px;box-sizing:border-box;width:100%;}
+.ex-mp-field input:focus-visible{outline:2px solid var(--gold);outline-offset:1px;}
+#exMpNameHint{font-size:11px;color:var(--muted);}
+#exMpNameBad,#exMpOffline{font-size:12.5px;line-height:1.45;color:var(--gold);}
+.ex-mp-btn{width:100%;padding:10px;font-weight:700;font-size:13px;color:#14191c;background:var(--gold);border-color:var(--gold);}
+.ex-mp-btn:hover:not(:disabled){background:var(--gold);}
+.ex-mp-btn:disabled{opacity:.45;cursor:not-allowed;}
+.ex-mp-btn:focus-visible{outline:2px solid #fff;outline-offset:2px;}
 /* Khi bay: chỉ còn ngôn ngữ, Ngày/Đêm, Chất lượng hình, dòng hướng dẫn và nút Thoát; mọi nút góc nhìn / cầu / Tour ẩn để không thoát chế độ bay bằng đường khác */
 #exHint,#exSpeed,#btnExExit,#exMpLabels,#exMpRoster,#exMpNotice{display:none;}
 body.explore #exSpeed{display:block;position:fixed;left:50%;transform:translateX(-50%);bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:6px 14px;font-size:13px;color:var(--text);direction:ltr;font-variant-numeric:tabular-nums;white-space:nowrap;pointer-events:none;}
 body.explore #exHint{display:block;position:fixed;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);text-align:center;max-width:calc(100vw - 32px);box-sizing:border-box;}
 body.explore #btnExExit{display:block;inset-inline-end:calc(14px + env(safe-area-inset-right,0px));top:calc(56px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);cursor:pointer;}
 body.explore #exMpLabels{display:block;position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:5;}
 .ex-mp-label{position:absolute;left:0;top:0;padding:2px 7px;font:500 11px/1.2 var(--font-body);color:var(--text);background:rgba(10,18,30,.72);border-radius:4px;white-space:nowrap;will-change:transform;direction:ltr;}
 .ex-mp-label[hidden]{display:none;}
 body.explore #exMpRoster:not([hidden]){display:flex;flex-direction:column;gap:3px;position:fixed;inset-inline-start:calc(14px + env(safe-area-inset-left,0px));top:calc(56px + env(safe-area-inset-top,0px));padding:8px 12px;font-size:12px;color:var(--text);pointer-events:none;z-index:5;}
 .ex-mp-head{font-weight:600;margin-bottom:2px;}
